class Solution {
public:
    int maxTurbulenceSize(vector<int>& arr) {
        int n = arr.size();
        if (n <= 1) return n;
        int max_len = 1, clen = 1, prev_sign = 0;
        for (int i = 0; i < n - 1; ++i) {
            int sign = (arr[i] > arr[i + 1]) ? 1 : ((arr[i] < arr[i + 1]) ? -1 : 0);
            if (sign == 0) {
                clen = 1;
            } else if (sign == -prev_sign) {
                clen++;
            } else {
                clen = 2;
            }
            prev_sign = sign;
            max_len = max(max_len, clen);
        }
        return max_len;
    }
};

class Solution {
    public int maxTurbulenceSize(int[] arr) {
        int n = arr.length;
        if (n <= 1) return n;
        int maxLen = 1, clen = 1, prevSign = 0;
        for (int i = 0; i < n - 1; i++) {
            int sign = Integer.compare(arr[i], arr[i + 1]);
            if (sign == 0) {
                clen = 1;
            } else if (sign == -prevSign) {
                clen++;
            } else {
                clen = 2;
            }
            prevSign = sign;
            maxLen = Math.max(maxLen, clen);
        }
        return maxLen;
    }
}

